// SAMPLE DATA. Replace this node with your CRM node (HubSpot, Salesforce, Pipedrive, Google Sheets...).
// Output one item per contact with: firstname, lastname, company, email.
return [
  { json: { firstname: 'Usama', lastname: 'bin Laden', company: 'Example Trading LLC', email: 'sample1@example.com' } },
  { json: { firstname: 'Jane', lastname: 'Doe', company: 'Banco Nacional de Cuba', email: 'sample2@example.com' } },
  { json: { firstname: 'Maria', lastname: 'Garcia', company: 'Northwind Test Co', email: 'sample3@example.com' } },
];

// Turn CRM contacts into a unique list of names to screen (person and company).
const cfg = $('Configuration').first().json;
const clean = (s) => (typeof s === 'string' ? s.trim().replace(/\s+/g, ' ') : '');
const owners = {};
const names = [];
for (const item of $input.all()) {
  const p = item.json;
  const email = clean(p.email);
  const person = clean(`${clean(p.firstname)} ${clean(p.lastname)}`);
  for (const n of [person, clean(p.company)]) {
    if (n.length < 3) continue;
    const key = n.toLowerCase();
    if (!owners[key]) { owners[key] = { name: n, contacts: [] }; names.push(n); }
    owners[key].contacts.push(email);
  }
}
if (!names.length) throw new Error('No names found. Check that your CRM node returns firstname, lastname or company.');
return [{ json: { names: names.slice(0, 5000), owners, minScore: Number(cfg.minScore) } }];

// Join Actor results back to CRM contacts and build one alert message.
const owners = $('Build unique names list').first().json.owners;
const hits = [];
const screened = $input.all().length;
for (const item of $input.all()) {
  const r = item.json;
  if (r.status !== 'potential_match') continue;
  const o = owners[String(r.name || '').toLowerCase()] || { contacts: [] };
  const top = (r.matches || [])[0] || {};
  hits.push({
    name: r.name,
    contacts: [...new Set(o.contacts)].join(', '),
    topScore: r.topScore,
    list: top.source || '',
    matched: top.matchedName || '',
    url: top.url || '',
  });
}

const lines = hits.map(h =>
  `- ${h.name} (CRM: ${h.contacts}) matched "${h.matched}" on ${h.list}, score ${h.topScore}. ${h.url}`);
const text = hits.length === 0 ? `No possible matches. ${screened} names screened.` : `${hits.length} possible sanctions match(es) in your CRM. Review each one by hand before acting. Common names give false positives.\n\n${lines.join('\n')}`;
return [{ json: { count: hits.length, screened, text, hits } }];
